113	// nodeFirst and nodeLast are the same sockets in two orders: the refresh of the
114	// table reorders them while a confirmation is open (DEVDESK-714).
115	func nodeFirst() []ports.Socket {
116		return []ports.Socket{sock("4242", "node"), sock("812", "sshd"), sock("1204", "nginx")}
117	}
118	
119	func nodeLast() []ports.Socket {
120		return []ports.Socket{sock("812", "sshd"), sock("1204", "nginx"), sock("4242", "node")}
121	}
