123	// confirmOnNode returns a wide model whose cursor is on node (PID 4242) with
124	// the confirmation open, and the fake that records signals.
125	func confirmOnNode(t *testing.T) (*Model, *fakeProcs) {
126		t.Helper()
127		m := feed(t, portsModel(t), tea.WindowSizeMsg{Width: 160, Height: 40})
128		m = feed(t, m, portsDataMsg{ports: nodeFirst()})
129		m.portsModel.table.Table().SetCursor(0)
130		procs := installProcs(m, false)
131		if row, ok := m.portsModel.table.Selected(); !ok || row.PID != "4242" {
132			t.Fatalf("setup: selected row = %+v, want node (PID 4242)", row)
133		}
134		m = feed(t, m, testutil.Key(keymap.Kill))
135		if m.portsModel.confirmModal == nil {
136			t.Fatal("setup: K on node did not open the confirmation")
137		}
138		return m, procs
139	}
