141	// runKill executes the command a confirmed Yes returned. It must be the kill
142	// command itself, with no footer timer batched in (that would sleep 3 s).
143	func runKill(t *testing.T, cmd tea.Cmd) portsKillResultMsg {
144		t.Helper()
145		if cmd == nil {
146			t.Fatal("Yes returned no command")
147		}
148		res, ok := cmd().(portsKillResultMsg)
149		if !ok {
150			t.Fatalf("the command did not return a portsKillResultMsg")
151		}
152		return res
153	}
