187	func TestYesKillsTheCapturedTargetAfterTheTableReorders(t *testing.T) {
188		m, procs := confirmOnNode(t)
189	
190		// The refresh lands before the user answers. The cursor stays on index 0,
191		// which is now sshd: the pre-fix code killed that row.
192		m = feed(t, m, portsDataMsg{ports: nodeLast()})
193		if row, _ := m.portsModel.table.Selected(); row.PID != "812" {
194			t.Fatalf("setup: after the reorder the selected row is %+v, want sshd (PID 812)", row)
195		}
196	
197		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
198		res := runKill(t, cmd)
199	
200		if res.pid != "4242" {
201			t.Errorf("kill result pid = %q, want 4242", res.pid)
202		}
203		if len(procs.killed) != 1 || procs.killed[0] != "4242" {
204			t.Errorf("signalled PIDs = %v, want exactly [4242] (never the selected row, 812)", procs.killed)
205		}
206		if !m.portsModel.table.IsBusy("4242") {
207			t.Error("the captured target is not marked busy")
208		}
209		if m.portsModel.table.IsBusy("812") {
210			t.Error("the row under the cursor was marked busy: Yes read the selection")
211		}
212		if m.portsModel.confirmModal != nil || m.portsModel.pendingKill != nil {
213			t.Error("the confirmation or its captured target survived Yes")
214		}
215	}
