272	func TestTheConfirmationDoesNotFollowTheSelection(t *testing.T) {
273		for _, tt := range []struct {
274			name string
275			then []tea.Msg
276		}{
277			{"the selection moves", append(testutil.Keys("down", "down", "up"), portsDataMsg{ports: nodeLast()})},
278			{"the process disappears", []tea.Msg{portsDataMsg{ports: []ports.Socket{sock("812", "sshd"), sock("1204", "nginx")}}}},
279			{"the table empties", []tea.Msg{portsDataMsg{ports: nil}}},
280		} {
281			t.Run(tt.name, func(t *testing.T) {
282				m, procs := confirmOnNode(t)
283				before := ansi.Strip(m.portsModel.confirmModal.View())
284	
285				m = feed(t, m, tt.then...)
286	
287				if m.portsModel.confirmModal == nil {
288					t.Fatal("the confirmation closed by itself")
289				}
290				if got := ansi.Strip(m.portsModel.confirmModal.View()); got != before {
291					t.Errorf("the confirmation text changed:\nbefore:\n%s\nafter:\n%s", before, got)
292				}
293				if want := (killTarget{PID: "4242", Process: "node", Identity: idOf("4242")}); m.portsModel.pendingKill == nil || *m.portsModel.pendingKill != want {
294					t.Errorf("pendingKill = %+v, want %+v", m.portsModel.pendingKill, want)
295				}
296				if len(procs.killed) != 0 {
297					t.Errorf("signalled %v without an answer", procs.killed)
