345	const goneWarning = "node (PID 4242) is no longer listed — not stopped"
346	
347	func TestYesOnAVanishedTargetSendsNothing(t *testing.T) {
348		for _, tt := range []struct {
349			name  string
350			table []ports.Socket
351		}{
352			{"the PID is gone", []ports.Socket{sock("812", "sshd"), sock("1204", "nginx")}},
353			{"the PID is back under another name", []ports.Socket{sock("4242", "python"), sock("812", "sshd")}},
354			{"the table is empty", nil},
355		} {
356			t.Run(tt.name, func(t *testing.T) {
357				m, procs := confirmOnNode(t)
358				m = feed(t, m, portsDataMsg{ports: tt.table})
359	
360				m, cmd := step(t, m, components.ConfirmModalYesMsg{})
361	
362				if len(procs.killed) != 0 {
363					t.Errorf("signalled %v for a target that is no longer listed", procs.killed)
364				}
365				if cmd == nil {
366					t.Error("no command returned, so the footer warning would never clear")
367				}
368				if got := m.portsModel.footer.Text(); got != goneWarning {
369					t.Errorf("footer = %q, want %q", got, goneWarning)
370				}
371				if got := m.portsModel.footer.Level(); got != components.LevelWarning {
372					t.Errorf("footer level = %v, want Warning (nothing failed, a precondition is unmet)", got)
373				}
374				if m.portsModel.confirmModal != nil || m.portsModel.pendingKill != nil {
375					t.Error("the confirmation stayed open after Yes")
376				}
377				if m.portsModel.table.IsBusy("4242") {
378					t.Error("the vanished target was marked busy")
379				}
380			})
381		}
382	}
