412	// targetPresence replaces targetStillListed (DEVDESK-709): the last table holds
413	// the target (present), holds that PID under another identity (replaced), or
414	// does not hold it (absent).
415	func TestTargetPresence(t *testing.T) {
416		m := feed(t, portsModel(t), portsDataMsg{ports: append(nodeFirst(),
417			sockWith("5000", "deferred", ports.DeferredIdentityForTest(time.Unix(1_700_000_000, 0))),
418		)})
419		pm := m.portsModel
420	
421		for _, tt := range []struct {
422			name   string
423			target killTarget
424			want   string
425		}{
426			{"same PID, same name, same identity", killTarget{PID: "4242", Process: "node", Identity: idOf("4242")}, "present"},
427			{"another listed process", killTarget{PID: "812", Process: "sshd", Identity: idOf("812")}, "present"},
428			{"same PID, same name, another identity", killTarget{PID: "4242", Process: "node", Identity: ports.IdentityForTest(99)}, "replaced"},
429			{"the row is deferred: it never conflicts", killTarget{PID: "5000", Process: "deferred", Identity: ports.IdentityForTest(1)}, "present"},
430			{"the target is deferred: it never conflicts", killTarget{PID: "4242", Process: "node", Identity: ports.DeferredIdentityForTest(time.Unix(1_700_000_000, 0))}, "present"},
431			{"same PID, another name, same identity", killTarget{PID: "4242", Process: "python", Identity: idOf("4242")}, "absent"},
432			{"unknown PID", killTarget{PID: "9999", Process: "node", Identity: idOf("9999")}, "absent"},
433			{"name of another row", killTarget{PID: "9999", Process: "sshd", Identity: idOf("9999")}, "absent"},
434		} {
435			t.Run(tt.name, func(t *testing.T) {
436				if got := classify(pm.targetPresence(tt.target), present, replaced, absent); got != tt.want {
437					t.Errorf("targetPresence(%+v) = %s, want %s", tt.target, got, tt.want)
438				}
439			})
440		}
441	}
