443	// Two sockets of one process are one process: the last table lists the PID
444	// twice and both rows carry the same identity.
445	func TestTargetPresenceReadsEveryRowOfThePID(t *testing.T) {
446		m := feed(t, portsModel(t), portsDataMsg{ports: append(nodeLast(), sock("4242", "node"))})
447	
448		got := m.portsModel.targetPresence(killTarget{PID: "4242", Process: "node", Identity: idOf("4242")})
449	
450		if classify(got, present, replaced, absent) != "present" {
451			t.Errorf("a PID listed twice with one identity is %s, want present", classify(got, present, replaced, absent))
452		}
453	}
