522	// S-02a criterion 2: one gesture, no wait, no second confirmation.
523	func TestWindowsStopIsOneGesture(t *testing.T) {
524		m, procs := windowsNode(t)
525	
526		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
527		if m.portsModel.confirmModal != nil {
528			t.Error("a second confirmation is open after Yes")
