20	// DEVDESK-717 (step 3 of DEVDESK-708): the confirmation of the Ports tab acts on
21	// the target it captured when it opened (S-01a criteria 5 and 6, bug
22	// DEVDESK-714), and says the truth on Windows (S-02a criteria 1 to 4).
23	//
24	// No test here reaches ports.Kill: every model installs a fake processOps whose
25	// kill only records the PID it was asked to signal.
26	
27	// fakeProcs records the PIDs the Ports tab asked to signal.
28	type fakeProcs struct {
29		killed []string
30		// killedWith records the identity each signal was asked to verify against
31		// (DEVDESK-709), in the order of killed.
32		killedWith []ports.Identity
33		err        error
34		// confirmed is the identity the confirmation reads for a PID, confirmErr the
35		// error it returns instead, confirmAsked every PID it was asked about. A PID
36		// in neither gets the identity it was listed with (DEVDESK-709).
37		confirmed    map[string]ports.Identity
38		confirmErr   map[string]error
39		confirmAsked []string
40		// protect is the verdict per PID; a PID not in it is Unprotected. asked
41		// records every PID the model asked about, in order (DEVDESK-718).
42		protect map[string]ports.Protection
43		asked   []string
44	}
45	
46	func (f *fakeProcs) ops(windows bool) processOps {
47		return processOps{
48			protection: func(pid string) ports.Protection {
49				f.asked = append(f.asked, pid)
50				return f.protect[pid]
51			},
52			confirm: func(pid string, listed ports.Identity) (ports.Identity, error) {
53				f.confirmAsked = append(f.confirmAsked, pid)
54				if err := f.confirmErr[pid]; err != nil {
55					return ports.Identity{}, err
56				}
57				if id, ok := f.confirmed[pid]; ok {
58					return id, nil
59				}
60				return listed, nil
61			},
62			kill: func(pid string, listed ports.Identity) error {
63				f.killed = append(f.killed, pid)
64				f.killedWith = append(f.killedWith, listed)
65				return f.err
66			},
67			windows: windows,
68		}
69	}
70	
71	// protectAs makes the fake say p about pid from now on.
72	func (f *fakeProcs) protectAs(pid string, p ports.Protection) {
73		if f.protect == nil {
74			f.protect = map[string]ports.Protection{}
75		}
76		f.protect[pid] = p
77	}
78	
79	// installProcs puts a fresh recording fake on the model and returns it.
80	func installProcs(m *Model, windows bool) *fakeProcs {
81		f := &fakeProcs{}
82		m.portsModel.ops = f.ops(windows)
83		return f
84	}
85	
86	// idOf is the identity the fixtures give the process with this PID: the PID
87	// itself, so two rows of one process agree and two processes differ. A row with
88	// no PID has none (DEVDESK-709).
89	func idOf(pid string) ports.Identity {
90		n, err := strconv.ParseUint(pid, 10, 64)
91		if err != nil {
92			return ports.Identity{}
93		}
94		return ports.IdentityForTest(n)
95	}
96	
97	// sock is a LISTEN socket held by pid; the port follows the PID so rows differ.
98	// Its identity is idOf(pid).
99	func sock(pid, process string) ports.Socket {
100		return sockWith(pid, process, idOf(pid))
101	}
102	
103	// sockWith is sock with an explicit identity: the zero value for a row DevDesk
104	// could not read, a deferred one for a Windows listing over its budget, or the
105	// stamp of another process holding the same PID.
106	func sockWith(pid, process string, id ports.Identity) ports.Socket {
107		return ports.Socket{
108			Protocol: "tcp", State: "LISTEN", LocalAddr: "0.0.0.0:" + pid, PeerAddr: "0.0.0.0:*",
109			PID: pid, Process: process, Identity: id,
110		}
111	}
112	
113	// nodeFirst and nodeLast are the same sockets in two orders: the refresh of the
114	// table reorders them while a confirmation is open (DEVDESK-714).
115	func nodeFirst() []ports.Socket {
116		return []ports.Socket{sock("4242", "node"), sock("812", "sshd"), sock("1204", "nginx")}
117	}
118	
119	func nodeLast() []ports.Socket {
120		return []ports.Socket{sock("812", "sshd"), sock("1204", "nginx"), sock("4242", "node")}
121	}
