155	// modalLines is the confirmation as rendered, border and padding removed, one
156	// entry per content line, stopping before the buttons.
157	func modalLines(m *Model) []string {
158		var out []string
159		for _, l := range strings.Split(ansi.Strip(m.portsModel.confirmModal.View()), "\n") {
160			l = strings.TrimSpace(strings.Trim(strings.TrimSpace(l), "│┌┐└┘─"))
161			if strings.Contains(l, "Yes") && strings.Contains(l, "No") {
162				break
163			}
164			out = append(out, l)
165		}
166		for len(out) > 0 && out[0] == "" {
167			out = out[1:]
168		}
169		for len(out) > 0 && out[len(out)-1] == "" {
170			out = out[:len(out)-1]
171		}
172		return out
173	}
