398	// classify names the outcome of targetPresence for a failure message without
399	// this file naming its type: got is compared with the three constants.
400	func classify[T comparable](got, isPresent, isReplaced, isAbsent T) string {
401		switch got {
402		case isPresent:
403			return "present"
404		case isReplaced:
405			return "replaced"
406		case isAbsent:
407			return "absent"
408		}
409		return "unknown"
410	}
