21	// DEVDESK-718 (step 4 of DEVDESK-708, S-01a criteria 1 to 3): K is greyed on a
22	// process DevDesk refuses to signal, the footer says why, no confirmation
23	// opens, and the row stays. The verdict comes from processOps.protection, which
24	// production wires to ports.ProtectionOf; every test but the wiring ones
25	// substitutes a fake, so no real PID is read and no signal can leave.
26	
27	// The wording agreed in the story, written out here so that a drift in the
28	// constants of internal/ports fails a test instead of following them silently.
29	const (
30		reasonSelfText    = "This is DevDesk itself"
31		reasonParentText  = "This process started DevDesk"
32		reasonInitText    = "PID 1 is the system's init process"
33		reasonWindowsText = "Windows system process"
34	)
35	
36	// protectedModel is a wide Ports model whose cursor is on the row (pid,
37	// process), which the fake says is p. A second, ordinary row follows it.
38	func protectedModel(t *testing.T, windows bool, pid, process string, p ports.Protection) (*Model, *fakeProcs) {
39		t.Helper()
40		m := feed(t, portsModel(t), tea.WindowSizeMsg{Width: 160, Height: 40})
41		m = feed(t, m, portsDataMsg{ports: []ports.Socket{sock(pid, process), sock("9001", "ordinary")}})
42		m.portsModel.table.Table().SetCursor(0)
43		procs := installProcs(m, windows)
44		procs.protectAs(pid, p)
45		if row, ok := m.portsModel.table.Selected(); !ok || row.PID != pid {
46			t.Fatalf("setup: selected row = %+v, want PID %s", row, pid)
47		}
48		return m, procs
49	}
50	
51	func visiblePIDs(m *Model) []string {
52		var out []string
53		for _, s := range m.portsModel.table.Visible() {
54			out = append(out, s.PID)
55		}
56		return out
57	}
58	
59	func contains(list []string, s string) bool {
60		for _, x := range list {
61			if x == s {
62				return true
63			}
64		}
65		return false
66	}
