68	// ── S-01a criteria 1, 2 and 3: greyed, with the reason, nothing opens ────────
69	
70	func TestKillIsGreyedOnAProtectedProcess(t *testing.T) {
71		for _, tt := range []struct {
72			name    string
73			windows bool
74			pid     string
75			process string
76			prot    ports.Protection
77			reason  string
78		}{
79			{"DevDesk itself (criterion 1)", false, "4242", "dk", ports.ProtectedSelf, reasonSelfText},
80			{"the process that started it (criterion 2)", false, "3100", "bash", ports.ProtectedParent, reasonParentText},
81			{"PID 1 (criterion 2)", false, "1", "systemd", ports.ProtectedInit, reasonInitText},
82			{"Windows PID 4 (criterion 3)", true, "4", "System", ports.ProtectedWindowsSystem, reasonWindowsText},
83			{"Windows PID 0 (criterion 3)", true, "0", "Idle", ports.ProtectedWindowsSystem, reasonWindowsText},
84		} {
85			t.Run(tt.name, func(t *testing.T) {
86				if got := tt.prot.Reason(); got != tt.reason {
87					t.Fatalf("setup: %v.Reason() = %q, want the agreed %q", tt.prot, got, tt.reason)
88				}
89				m, procs := protectedModel(t, tt.windows, tt.pid, tt.process, tt.prot)
90	
91				// Rule 130: advertised, greyed, same label.
92				if !testutil.HasShortcut(m.GetShortcuts(), keymap.Kill) {
93					t.Fatal("K disappeared from the header instead of being greyed")
94				}
95				if !testutil.ShortcutDisabled(m.GetShortcuts(), keymap.Kill) {
96					t.Error("K is offered on a process DevDesk refuses to signal")
97				}
98				for _, s := range m.GetShortcuts() {
99					if s.Key == keymap.Kill && s.Description != "Kill process" {
100						t.Errorf("greyed K reads %q, want its own label %q", s.Description, "Kill process")
101					}
102				}
103	
104				next, cmd := step(t, m, testutil.Key(keymap.Kill))
105	
106				if next.portsModel.confirmModal != nil {
107					t.Error("K opened the confirmation on a protected process")
108				}
109				if next.portsModel.pendingKill != nil {
110					t.Errorf("K captured a target on a protected process: %+v", next.portsModel.pendingKill)
111				}
112				if got := next.portsModel.footer.Text(); got != tt.reason {
113					t.Errorf("footer = %q, want exactly the reason %q", got, tt.reason)
114				}
115				if got := next.portsModel.footer.Level(); got != components.LevelWarning {
116					t.Errorf("footer level = %v, want Warning (nothing failed: Rules 128 and 130)", got)
117				}
118				if cmd == nil {
119					t.Error("the refusal returned no command, so its footer line would never clear")
120				}
121				if !contains(visiblePIDs(next), tt.pid) {
122					t.Errorf("the row of PID %s left the table (visible: %v)", tt.pid, visiblePIDs(next))
123				}
124				if row, ok := next.portsModel.table.Selected(); !ok || row.PID != tt.pid {
125					t.Errorf("the selection moved off the protected row: %+v", row)
126				}
127				if next.portsModel.InEditMode() {
128					t.Error("the refused K left the view in edit mode")
129				}
130				if len(procs.killed) != 0 {
131					t.Errorf("signalled %v", procs.killed)
132				}
133			})
134		}
135	}
