137	func TestKillStaysOfferedOnAnOrdinaryProcess(t *testing.T) {
138		m, procs := protectedModel(t, false, "4242", "dk", ports.ProtectedSelf)
139		m = feed(t, m, testutil.Key("down")) // the ordinary row
140	
141		if row, _ := m.portsModel.table.Selected(); row.PID != "9001" {
142			t.Fatalf("setup: selected row = %+v, want the ordinary row", row)
143		}
144		if !testutil.ShortcutEnabled(m.GetShortcuts(), keymap.Kill) {
145			t.Error("K is greyed on an unprotected process")
146		}
147	
148		m = feed(t, m, testutil.Key(keymap.Kill))
149	
150		if m.portsModel.confirmModal == nil {
151			t.Fatal("K on an unprotected process did not open the confirmation")
152		}
153		if want := (killTarget{PID: "9001", Process: "ordinary", Identity: idOf("9001")}); m.portsModel.pendingKill == nil || *m.portsModel.pendingKill != want {
154			t.Errorf("pendingKill = %+v, want %+v", m.portsModel.pendingKill, want)
155		}
156		if len(procs.killed) != 0 {
157			t.Errorf("signalled %v before an answer", procs.killed)
158		}
159	}
