161	// The verdict follows the cursor on every render: nothing is cached from the
162	// row K was last greyed on.
163	func TestTheGreyFollowsTheCursor(t *testing.T) {
164		m, _ := protectedModel(t, false, "4242", "dk", ports.ProtectedSelf)
165	
166		for i, tc := range []struct {
167			key  string
168			want bool // K enabled
169		}{
170			{"", false}, {"down", true}, {"up", false}, {"down", true},
171		} {
172			if tc.key != "" {
173				m = feed(t, m, testutil.Key(tc.key))
174			}
175			if got := testutil.ShortcutEnabled(m.GetShortcuts(), keymap.Kill); got != tc.want {
176				row, _ := m.portsModel.table.Selected()
177				t.Errorf("step %d (%q, row %s): K enabled = %v, want %v", i, tc.key, row.PID, got, tc.want)
178			}
179		}
180	}
