182	// Rule 130: the set of keys is the same on a protected row and an ordinary one.
183	func TestTheKeySetDoesNotChangeOnAProtectedRow(t *testing.T) {
184		m, _ := protectedModel(t, false, "4242", "dk", ports.ProtectedSelf)
