195	func TestYesRechecksTheCapturedTarget(t *testing.T) {
196		t.Run("a target that became protected is not signalled", func(t *testing.T) {
197			m, procs := confirmOnNode(t)
198			procs.protectAs("4242", ports.ProtectedSelf) // after the confirmation opened
199	
200			m, cmd := step(t, m, components.ConfirmModalYesMsg{})
201	
202			if len(procs.killed) != 0 {
203				t.Errorf("signalled %v: a PID that became protected between K and Yes", procs.killed)
204			}
205			if cmd == nil {
206				t.Error("no command returned, so the footer warning would never clear")
207			}
208			if got := m.portsModel.footer.Text(); !strings.Contains(got, reasonSelfText) {
209				t.Errorf("footer = %q, want it to carry %q", got, reasonSelfText)
210			}
211			if got := m.portsModel.footer.Level(); got != components.LevelWarning {
212				t.Errorf("footer level = %v, want Warning", got)
213			}
214			if m.portsModel.table.IsBusy("4242") {
215				t.Error("the refused target was marked busy")
216			}
217			if m.portsModel.confirmModal != nil || m.portsModel.pendingKill != nil {
218				t.Error("the confirmation stayed open after Yes")
219			}
220		})
221	
222		t.Run("the captured target is rechecked, not the row under the cursor", func(t *testing.T) {
223			m, procs := confirmOnNode(t)
224			m = feed(t, m, portsDataMsg{ports: nodeLast()}) // the cursor is now on sshd, PID 812
225			procs.protectAs("812", ports.ProtectedParent)   // the selection is protected; the target is not
226	
227			_, cmd := step(t, m, components.ConfirmModalYesMsg{})
228			runKill(t, cmd)
229	
230			if len(procs.killed) != 1 || procs.killed[0] != "4242" {
231				t.Errorf("signalled %v, want [4242]: the verdict on the selected row must not decide", procs.killed)
232			}
233		})
234	
235		t.Run("a protected target is refused though another row is the selection", func(t *testing.T) {
236			m, procs := confirmOnNode(t)
237			m = feed(t, m, portsDataMsg{ports: nodeLast()})
238			procs.protectAs("4242", ports.ProtectedSelf)
239	
240			m, _ = step(t, m, components.ConfirmModalYesMsg{})
241	
242			if len(procs.killed) != 0 {
243				t.Errorf("signalled %v", procs.killed)
244			}
245			if got := m.portsModel.footer.Text(); !strings.Contains(got, reasonSelfText) {
246				t.Errorf("footer = %q, want it to carry %q", got, reasonSelfText)
247			}
248		})
249	
250		t.Run("an unprotected target is signalled as before", func(t *testing.T) {
251			m, procs := confirmOnNode(t)
252	
253			_, cmd := step(t, m, components.ConfirmModalYesMsg{})
254			runKill(t, cmd)
