21	// DEVDESK-709 (S-01b, criteria 2, 4, 6 and 7 on the interface side): K verifies
22	// which process a row is. It is greyed when DevDesk cannot tell, the signal
23	// goes with the identity the row was listed with, a changed identity sends
24	// nothing and re-reads the table, and a deferred identity (Windows, over the
25	// listing budget) is read when the confirmation opens.
26	//
27	// Nothing here reaches ports.Kill, ports.ConfirmIdentity or ports.List: every
28	// model installs a fakeProcs. A test that drains a Cmd shortens the footer timer
29	// first (testutil.FastTimers), and no test runs the command a portsRefreshMsg
30	// leads to, since it would read the real socket table.
31	
32	// The sentences of the story, written out so that a drift in the constants of
33	// this package or of internal/ports fails a test instead of following them.
34	const (
35		unverifiableText       = "Cannot verify which process this is"
36		changedWarning         = "node (PID 4242) is no longer the process that was listed — table refreshed"
37		deferredChangedWarning = "node.exe (PID 4412) is no longer the process that was listed — table refreshed"
38		unverifiableAtSignal   = "Cannot verify which process PID 4242 is — not stopped"
39		refusedByTheSystem4412 = "Refused by the system — DevDesk cannot signal PID 4412"
40	)
41	
42	// listedAt is the instant a Windows listing stamped on the rows it deferred.
43	var listedAt = time.Unix(1_700_000_000, 0)
44	
45	// identityModel is a wide Ports model whose cursor is on rows[0], with the
46	// recording fake installed.
47	func identityModel(t *testing.T, windows bool, rows ...ports.Socket) (*Model, *fakeProcs) {
48		t.Helper()
49		m := feed(t, portsModel(t), tea.WindowSizeMsg{Width: 160, Height: 40})
50		m = feed(t, m, portsDataMsg{ports: rows})
51		m.portsModel.table.Table().SetCursor(0)
52		procs := installProcs(m, windows)
53		if row, ok := m.portsModel.table.Selected(); !ok || row.PID != rows[0].PID {
54			t.Fatalf("setup: selected row = %+v, want PID %s", row, rows[0].PID)
55		}
56		return m, procs
57	}
