94	// outcome is what a refusal leaves behind: the footer line, its level, and how
95	// many reads of the table it asked for.
96	type outcome struct {
97		text      string
98		level     components.Level
99		refreshes int
100	}
101	
102	// outcomeOf drains cmd (the footer timer is shortened by the caller) and reads
103	// the footer.
104	func outcomeOf(m *Model, cmd tea.Cmd) outcome {
105		msgs := testutil.Msgs(cmd)
106		return outcome{
107			text:      m.portsModel.footer.Text(),
108			level:     m.portsModel.footer.Level(),
109			refreshes: countRefreshes(msgs),
110		}
111	}
