671			{"cannot verify, cause is an OS refusal", &ports.UnverifiableError{PID: 4412, Cause: os.ErrPermission}, outcome{"Cannot verify which process PID 4412 is — not stopped", components.LevelWarning, 0}},
672			{"refused by the system", os.ErrPermission, outcome{refusedByTheSystem4412, components.LevelError, 0}},
673			{"gone", os.ErrProcessDone, outcome{"PID 4412 is no longer running", components.LevelError, 0}},
674			{"anything else", errors.New("operation not permitted"), outcome{"Failed to kill PID 4412 — check logs", components.LevelError, 0}},
675			{"protected", &ports.ProtectedError{PID: 4412, Protection: ports.ProtectedSelf}, outcome{"PID 4412 not stopped: " + reasonSelfText, components.LevelWarning, 0}},
676		} {
