92		if !m.portsModel.stale {
93			t.Fatal("the failure was not recorded as staleness")
94		}
95		// Rule 128: this is a state, not an event. A message would expire, and its
96		// expiry is exactly what made a dead table look alive.
97		if m.portsModel.footer.IsSet() {
98			t.Errorf("footer = %q; staleness belongs to the status line, which has no timer",
