100		}
101		if cmd != nil {
102			t.Error("a command was returned for a state that needs no timer")
103		}
104	
105		status := m.portsModel.statusLine().Text
106		if !strings.Contains(status, "could not be read") {
107			t.Errorf("status = %q, does not say the socket table could not be read", status)
108		}
109		if !strings.Contains(status, "as of") {
110			t.Errorf("status = %q, does not date the rows on screen", status)
111		}
112		if strings.Contains(status, "cannot connect") {
113			t.Errorf("status = %q leaks the raw error; Rule 128 wants a short line plus a log", status)
114		}
115	}
