	}

	// The tick that was in flight arrives anyway, at the deadline: it is stale.
	before := m.portsModel.footer.Text()
	m, cmd = step(t, m, portsStopProbeMsg{gen: oldGen, at: afterGrace, liveness: ports.ProcessRunning})
