			t.Errorf("footer line at 80 columns = %q, want exactly %q", got, stopPendingHereText)
		}
		footerFits(t, m, 80)

		m = feed(t, feed(t, m, testutil.Key("down")), testutil.Key(keymap.Kill))
		if got := infoLine(m, 80); got != anotherStopText {
