		footerFits(t, escaped, 80)
		if line := infoLine(escaped, 80); ansi.StringWidth(line) > 80 || !strings.HasPrefix(line, "Stopped waiting for") {
			t.Errorf("footer line = %q, want a cut line that still starts the sentence", line)
		}

		stopped, _ := probeAt(t, m, stopT0.Add(time.Second), ports.ProcessExited, nil)
		footerFits(t, stopped, 80)
